INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Verbessert Netzwerksegmentierung die Sicherheit?', 2, '[{"text": "Ja", "correct": true, "because": "Isoliert Bereiche"}, {"text": "Nein", "correct": false, "because": "Hauptvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Vorteil bietet Segmentierung für die Effizienz?', 3, '[{"text": "Reduziert Broadcast-Verkehr", "correct": true, "because": "Kleinere Domänen"}, {"text": "Erhöht Bandbreite", "correct": false, "because": "Indirekt"}, {"text": "Verkürzt Kabel", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Segmentierung schützt vor internen Angriffen. b) Sie macht das Netz langsamer.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) verbessert Effizienz"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Netzwerksegmentierung?', 4, '[{"text": "Subnetzmaske", "correct": false, "because": "Definiert Segmente"}, {"text": "Sicherheitszonen", "correct": false, "because": "Schützen Bereiche"}, {"text": "Farbschema", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Segmentierung den Datenverkehr reduziert?', 2, '[{"text": "Ja", "correct": true, "because": "Weniger Broadcasts"}, {"text": "Nein", "correct": false, "because": "Effizienzvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Methode segmentiert ein Netzwerk effektiv?', 3, '[{"text": "Subnetzing", "correct": true, "because": "Teilt in Subnetze"}, {"text": "Statische IPs", "correct": false, "because": "Keine Segmentierung"}, {"text": "Hohe Bandbreite", "correct": false, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Ziele verfolgt die Segmentierung?', 5, '[{"text": "Sicherheit erhöhen", "correct": true, "because": "Isoliert Bedrohungen"}, {"text": "Effizienz steigern", "correct": true, "because": "Optimiert Verkehr"}, {"text": "Kosten senken", "correct": false, "because": "Indirekt"}, {"text": "Bandbreite verdoppeln", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Segmentierung verhindert Broadcast-Stürme. b) Sie ist nur für große Netze. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) auch kleine Netze"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Segmentierung?', 4, '[{"text": "Subnetzmaske", "correct": false, "because": "Definiert Segmente"}, {"text": "Router", "correct": false, "because": "Trennt Segmente"}, {"text": "Grafische Oberfläche", "correct": true, "because": "Optional"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Teilt /26 192.168.1.0/24 in 4 Segmente?', 2, '[{"text": "Ja", "correct": true, "because": "2^(26-24) = 4"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Segment ist sicherer bei 192.168.1.0/24 mit /26?', 4, '[{"text": "192.168.1.64-127", "correct": true, "because": "Isoliert von anderen"}, {"text": "192.168.1.0-255", "correct": false, "because": "Kein Segment"}, {"text": "192.168.1.0-63", "correct": false, "because": "Gleich sicher"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Segmentierung die Effizienz senkt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Steigert Effizienz"}, {"text": "Ja", "correct": false, "because": "Falsches Verständnis"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Segmentierung?', 3, '[{"text": "Sicherheitszonen", "correct": true, "because": "Schützt sensible Bereiche"}, {"text": "Schnelligkeit", "correct": false, "because": "Funktion zählt"}, {"text": "Zufälligkeit", "correct": false, "because": "Struktur nötig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Segmentierung nutzt Subnetze. b) Sie erhöht Kollisionen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) reduziert Kollisionen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile hat Segmentierung bei 10.0.0.0/24?', 5, '[{"text": "Weniger Broadcasts", "correct": true, "because": "Kleinere Domänen"}, {"text": "Bessere Sicherheit", "correct": true, "because": "Isolierte Segmente"}, {"text": "Höhere Bandbreite", "correct": false, "because": "Indirekt"}, {"text": "Weniger Hardware", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Segmentierung unwichtig?', 3, '[{"text": "Subnetzgröße", "correct": false, "because": "Bestimmt Effizienz"}, {"text": "Sicherheitsrichtlinien", "correct": false, "because": "Schützen Segmente"}, {"text": "Schriftgröße", "correct": true, "because": "Technisch irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Hat /27 bei 192.168.1.0/24 8 Segmente?', 3, '[{"text": "Ja", "correct": true, "because": "2^(27-24) = 8"}, {"text": "Nein", "correct": false, "because": "Korrekte Berechnung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Segmentierung den Verwaltungsaufwand erhöht?', 2, '[{"text": "Ja", "correct": true, "because": "Mehr Subnetze zu managen"}, {"text": "Nein", "correct": false, "because": "Realistischer Aufwand"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Bereich ist das zweite Segment bei 172.16.0.0/24 mit /25?', 4, '[{"text": "172.16.0.128-172.16.0.255", "correct": true, "because": "Inkrement 128"}, {"text": "172.16.0.64-172.16.0.127", "correct": false, "because": "Für /26"}, {"text": "172.16.0.0-172.16.0.127", "correct": false, "because": "Erstes Segment"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maske segmentiert 10.0.0.0/24 in 4 sichere Bereiche?', 3, '[{"text": "/26", "correct": true, "because": "2^(26-24) = 4 Subnetze"}, {"text": "/25", "correct": false, "because": "Nur 2 Subnetze"}, {"text": "/27", "correct": false, "because": "8 Subnetze"}]');
